127	    ) : hasAttachments ? null : (
128	      <div className="text-sm text-muted-foreground truncate min-w-0">No content</div>
129	    )
130	  ) : (
131	    // Previews are inert (pointer-events-none), so a static CSS bound replaces the
132	    // interactive clamp a full memo card gets.
133	    hasContent && (
134	      <div className="max-h-36 w-full overflow-hidden">
135	        <MemoContent content={content} compact={compact} />
136	      </div>
137	    )
138	  );
139	
140	  return (
141	    <MemoViewContext.Provider value={STUB_CONTEXT}>
142	      <div
143	        className={cn(
144	          "pointer-events-none",
145	          truncate ? "flex items-center gap-1.5 min-w-0 leading-tight" : "flex flex-col gap-1",
146	          className,
147	        )}
148	      >
149	        {showMeta && meta}
150	        {showMeta && truncate && (hasContent || hasAttachments) && <div className="text-muted-foreground/50 shrink-0">·</div>}
151	        {contentNode}
152	        {hasAttachments &&
153	          (truncate ? (
154	            <div className="shrink-0 text-muted-foreground/70 inline-flex justify-center items-center gap-0.5">
155	              <FileIcon className="w-3 h-3 inline-block" />
156	              <span className="text-xs">{countLogicalAttachmentItems(attachments)}</span>
157	            </div>
158	          ) : (
159	            <AttachmentThumbnails attachments={attachments} />
160	          ))}
161	      </div>
162	    </MemoViewContext.Provider>
163	  );
164	};
