5	export type FilterFactor =
6	  | "tagSearch"
7	  | "visibility"
8	  | "contentSearch"
9	  | "displayTime"
10	  | "pinned"
11	  | "property.hasLink"
12	  | "property.hasTaskList"
13	  | "property.hasCode";
