15	export interface MemoFilter {
16	  factor: FilterFactor;
17	  value: string;
18	}
19	
20	export const getMemoFilterKey = (filter: MemoFilter): string => `${filter.factor}:${filter.value}`;
21	
22	export const parseFilterQuery = (query: string | null): MemoFilter[] => {
23	  if (!query) return [];
24	  try {
25	    return query.split(",").map((filterStr) => {
26	      const [factor, value] = filterStr.split(":");
27	      return {
28	        factor: factor as FilterFactor,
29	        value: decodeURIComponent(value || ""),
30	      };
31	    });
32	  } catch {
33	    return [];
34	  }
35	};
36	
37	export const stringifyFilters = (filters: MemoFilter[]): string => {
38	  return filters.map((filter) => `${filter.factor}:${encodeURIComponent(filter.value)}`).join(",");
39	};
40	
41	interface MemoFilterContextValue {
42	  filters: MemoFilter[];
43	  shortcut: string | undefined;
44	  hasActiveFilters: boolean;
45	  getFiltersByFactor: (factor: FilterFactor) => MemoFilter[];
46	  setFilters: (filters: MemoFilter[]) => void;
47	  addFilter: (filter: MemoFilter) => void;
48	  removeFilter: (predicate: (f: MemoFilter) => boolean) => void;
49	  removeFiltersByFactor: (factor: FilterFactor) => void;
50	  clearAllFilters: () => void;
51	  setShortcut: (shortcut?: string) => void;
52	  hasFilter: (filter: MemoFilter) => boolean;
53	}
54	
55	const MemoFilterContext = createContext<MemoFilterContextValue | null>(null);
56	
57	export function MemoFilterProvider({ children }: { children: ReactNode }) {
58	  const [searchParams, setSearchParams] = useSearchParams();
59	  const lastSyncedUrlRef = useRef("");
60	  const lastSyncedStoreRef = useRef("");
61	
62	  // Initialize from URL
63	  const [filters, setFiltersState] = useState<MemoFilter[]>(() => {
64	    return parseFilterQuery(searchParams.get("filter"));
65	  });
66	  const [shortcut, setShortcutState] = useState<string | undefined>(undefined);
67	
68	  // Sync URL to state when URL changes externally
69	  useEffect(() => {
70	    const filterParam = searchParams.get("filter") || "";
71	    if (filterParam !== lastSyncedUrlRef.current) {
72	      lastSyncedUrlRef.current = filterParam;
73	      const newFilters = parseFilterQuery(filterParam);
74	      setFiltersState(newFilters);
75	      lastSyncedStoreRef.current = stringifyFilters(newFilters);
76	    }
77	  }, [searchParams]);
78	
79	  // Sync state to URL when state changes
80	  useEffect(() => {
81	    const storeString = stringifyFilters(filters);
82	    if (storeString !== lastSyncedStoreRef.current && storeString !== lastSyncedUrlRef.current) {
83	      lastSyncedStoreRef.current = storeString;
84	      const newParams = new URLSearchParams(searchParams);
85	      if (filters.length > 0) {
86	        newParams.set("filter", storeString);
87	      } else {
88	        newParams.delete("filter");
89	      }
90	      setSearchParams(newParams, { replace: true });
91	      lastSyncedUrlRef.current = filters.length > 0 ? storeString : "";
92	    }
93	  }, [filters, searchParams, setSearchParams]);
94	
95	  const getFiltersByFactor = useCallback((factor: FilterFactor) => filters.filter((f) => f.factor === factor), [filters]);
96	
97	  const setFilters = useCallback((newFilters: MemoFilter[]) => {
98	    setFiltersState(newFilters);
99	  }, []);
100	
101	  const addFilter = useCallback((filter: MemoFilter) => {
102	    setFiltersState((prev) => uniqBy([...prev, filter], getMemoFilterKey));
103	  }, []);
104	
105	  const removeFilter = useCallback((predicate: (f: MemoFilter) => boolean) => {
106	    setFiltersState((prev) => prev.filter((f) => !predicate(f)));
107	  }, []);
108	
109	  const removeFiltersByFactor = useCallback((factor: FilterFactor) => {
110	    setFiltersState((prev) => prev.filter((f) => f.factor !== factor));
111	  }, []);
112	
113	  const clearAllFilters = useCallback(() => {
114	    setFiltersState([]);
115	    setShortcutState(undefined);
116	  }, []);
117	
118	  const setShortcut = useCallback((newShortcut?: string) => {
119	    setShortcutState(newShortcut);
120	    // Clear content search filter when selecting a shortcut (issue #5462)
121	    if (newShortcut !== undefined) {
122	      setFiltersState((prev) => prev.filter((f) => f.factor !== "contentSearch"));
123	    }
124	  }, []);
125	
126	  const hasFilter = useCallback((filter: MemoFilter) => filters.some((f) => getMemoFilterKey(f) === getMemoFilterKey(filter)), [filters]);
127	
128	  const hasActiveFilters = filters.length > 0 || shortcut !== undefined;
129	
130	  return (
131	    <MemoFilterContext.Provider
132	      value={{
133	        filters,
134	        shortcut,
135	        hasActiveFilters,
136	        getFiltersByFactor,
137	        setFilters,
138	        addFilter,
139	        removeFilter,
140	        removeFiltersByFactor,
141	        clearAllFilters,
142	        setShortcut,
143	        hasFilter,
144	      }}
145	    >
146	      {children}
147	    </MemoFilterContext.Provider>
148	  );
149	}
150	
151	export function useMemoFilterContext() {
152	  const context = useContext(MemoFilterContext);
153	  if (!context) {
154	    throw new Error("useMemoFilterContext must be used within MemoFilterProvider");
155	  }
156	  return context;
157	}
158	
159	// Alias for backwards compatibility during migration
160	export const useMemoFilter = useMemoFilterContext;
